import 'dart:ui' as ui;

import 'package:flutter/material.dart';

/// Sunrise over the «Тропа к солнцу» (9A) icon landscape: plays for 1.5 s when the app starts
/// and when it comes back after more than an hour in the background, then dissolves into the app.
/// A tap skips it; the SOS screen dismisses it at once ([SunriseSplash.dismiss]).
class SunriseSplash extends StatefulWidget {
  const SunriseSplash({super.key});

  static final _dismissed = ValueNotifier(0);

  /// Hides the sunrise right away (e.g. the app was opened straight into SOS).
  static void dismiss() => _dismissed.value++;

  @override
  State<SunriseSplash> createState() => _SunriseSplashState();
}

class _SunriseSplashState extends State<SunriseSplash> with SingleTickerProviderStateMixin {
  static const _replayAfter = Duration(hours: 1);

  late final _controller = AnimationController(vsync: this, duration: const Duration(milliseconds: 1500))
    ..addStatusListener((s) {
      if (s == AnimationStatus.completed) setState(() => _playing = false);
    });
  late final AppLifecycleListener _lifecycle;
  bool _playing = true;
  DateTime? _hiddenAt;

  @override
  void initState() {
    super.initState();
    _lifecycle = AppLifecycleListener(onHide: () => _hiddenAt = DateTime.now(), onShow: _onShow);
    SunriseSplash._dismissed.addListener(_dismiss);
    WidgetsBinding.instance.addPostFrameCallback((_) => _play());
  }

  void _onShow() {
    final hiddenAt = _hiddenAt;
    _hiddenAt = null;
    if (hiddenAt != null && DateTime.now().difference(hiddenAt) > _replayAfter) _play();
  }

  void _play() {
    if (!mounted) return;
    if (MediaQuery.disableAnimationsOf(context)) return _dismiss();
    setState(() => _playing = true);
    _controller.forward(from: 0);
  }

  void _dismiss() {
    if (!mounted) return;
    _controller.stop();
    setState(() => _playing = false);
  }

  @override
  void dispose() {
    SunriseSplash._dismissed.removeListener(_dismiss);
    _lifecycle.dispose();
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!_playing) return const SizedBox.shrink();
    final background = Theme.of(context).colorScheme.surface;
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      // A tap goes straight to the final dissolve.
      onTap: () => _controller.value < .8 ? _controller.forward(from: .8) : null,
      child: AnimatedBuilder(
        animation: _controller,
        builder: (context, _) {
          final t = _controller.value;
          final fadeOut = Curves.easeIn.transform(((t - .8) / .2).clamp(0, 1));
          final appear = Curves.easeOut.transform((t / .15).clamp(0, 1));
          return Opacity(
            opacity: 1 - fadeOut,
            child: ColoredBox(
              color: background,
              child: Center(
                child: Transform.scale(
                  scale: .92 + .08 * appear + .1 * fadeOut,
                  child: Opacity(
                    opacity: appear,
                    child: LayoutBuilder(
                      builder: (context, c) {
                        final side = (c.biggest.shortestSide * .5).clamp(0.0, 260.0);
                        return ClipRRect(
                          borderRadius: BorderRadius.circular(side * .22),
                          child: CustomPaint(
                            size: Size.square(side),
                            painter: _SunrisePainter(Curves.easeOutCubic.transform(((t - .05) / .65).clamp(0, 1))),
                          ),
                        );
                      },
                    ),
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );
  }
}

/// The 9A icon (1024 × 1024 units) with the sun [rise] of the way up from behind the first hill.
class _SunrisePainter extends CustomPainter {
  _SunrisePainter(this.rise);

  final double rise;

  static const _sunX = 512.0, _sunTop = 462.0, _sunBottom = 720.0, _sunRadius = 116.0;
  static final _paths = [for (final (color, points) in _shapes) (color, _parse(points))];

  static Path _parse(String points) {
    final v = points.split(' ').map(double.parse).toList();
    final path = Path()..moveTo(v[0], v[1]);
    for (var i = 2; i < v.length; i += 2) {
      path.lineTo(v[i], v[i + 1]);
    }
    return path..close();
  }

  @override
  void paint(Canvas canvas, Size size) {
    canvas.scale(size.width / 1024);
    const full = Rect.fromLTWH(0, 0, 1024, 1024);
    // Dawn: the sky warms up to the icon's colours as the sun comes up.
    final skyTop = Color.lerp(const Color(0xFFD5E4EA), const Color(0xFFEEFCF8), rise)!;
    final skyBottom = Color.lerp(const Color(0xFFB7D9DA), const Color(0xFFCBF2E8), rise)!;
    canvas.drawRect(full, Paint()..shader = ui.Gradient.linear(Offset.zero, const Offset(0, 700), [skyTop, skyBottom]));
    final sunY = ui.lerpDouble(_sunBottom, _sunTop, rise)!;
    const glow = Color(0xFFFCE4C6);
    canvas.drawCircle(
      Offset(_sunX, sunY),
      360,
      Paint()
        ..shader = ui.Gradient.radial(
          Offset(_sunX, sunY),
          360,
          [glow.withValues(alpha: rise), glow.withValues(alpha: .55 * rise), glow.withValues(alpha: 0)],
          [0, .45, 1],
        ),
    );
    // The sun is drawn under the hills, so it comes up from behind the first one.
    canvas.drawCircle(Offset(_sunX, sunY), _sunRadius, Paint()..color = const Color(0xFFF4B77E));
    for (final (color, path) in _paths) {
      canvas.drawPath(path, Paint()..color = color);
    }
  }

  @override
  bool shouldRepaint(_SunrisePainter old) => old.rise != rise;
}

